// Generated by tools/voice.py pack. Do not edit: edit RelayStory/MissionCatalog, then regenerate.
// Every voiced line: its bank, region (seconds), speaker, tape treatment and exact on-screen text.
export interface VoiceCue { bank: string; start: number; finish: number; speaker: string; tape: boolean; radio: boolean; text: string }
export const VOICE_CUES: Record<string, VoiceCue> = {
	"story.c00.b00": { bank: "voiceBank01", start: 0.250, finish: 8.269, speaker: "TEAL", tape: true, radio: false, text: "Two taps. That's me. If you're hearing this, I missed a check-in, and you're sitting in my chair because nobody else wanted the paperwork." },
	"story.c00.b01": { bank: "voiceBank01", start: 8.519, finish: 15.793, speaker: "SERA", tape: false, radio: false, text: "He missed three. He told me once: one check-in is weather, two is trouble, three is worry. I've been worried since Tuesday." },
	"story.c00.b02": { bank: "voiceBank01", start: 16.043, finish: 22.958, speaker: "TEAL", tape: true, radio: false, text: "Sparrow. You fly the pattern too low and too fast, and I never fixed it, because it's the only thing you do without asking permission." },
	"story.c00.b03": { bank: "voiceBank01", start: 23.208, finish: 29.025, speaker: "SERA", tape: false, radio: false, text: "Command calls it desertion. They made me say the word on the net. I said it. I'm not saying it again." },
	"story.c00.b04": { bank: "voiceBank01", start: 29.275, finish: 33.624, speaker: "TEAL", tape: true, radio: false, text: "If I miss your checkout, fly the pattern anyway. The sky will still be there." },
	"story.c00.b05": { bank: "voiceBank01", start: 33.874, finish: 37.602, speaker: "TRAINEE", tape: false, radio: false, text: "An empty chair and a checkout nobody's signing. Fine. I'll fly the pattern." },
	"story.c01.b00": { bank: "voiceBank01", start: 37.852, finish: 43.851, speaker: "SERA", tape: false, radio: false, text: "The bombers wore our markings. Our paint, our numbers. One of them was a tail I cleared for departure in March." },
	"story.c01.b01": { bank: "voiceBank01", start: 44.101, finish: 50.986, speaker: "SERA", tape: false, radio: false, text: "The quartermaster found a case under Teal's bunk. A coffee tin, twelve tapes, and a note: 'For Sera. Not for the net.'" },
	"story.c01.b02": { bank: "voiceBank01", start: 51.236, finish: 59.933, speaker: "TEAL", tape: true, radio: false, text: "Keep these off the command net. Somebody up there is listening and signing things they shouldn't. If I go quiet, the case goes to Sera. Only Sera." },
	"story.c01.b03": { bank: "voiceBank01", start: 60.183, finish: 67.708, speaker: "TEAL", tape: true, radio: false, text: "The manifest sends grain drums to a farm with a runway, then five quays on Iron Coast. Nobody ships grain in drums." },
	"story.c01.b04": { bank: "voiceBank01", start: 67.958, finish: 74.158, speaker: "SERA", tape: false, radio: false, text: "There are real houses in that yard. Families who work the siding. I need you to come home with the right number of fires." },
	"story.c01.b05": { bank: "voiceBank01", start: 74.408, finish: 80.808, speaker: "SERA", tape: false, radio: false, text: "Iron Coast is a hundred miles of our own shoreline. Whoever this is, they're not invading. They're already home." },
	"story.c01.b06": { bank: "voiceBank01", start: 81.058, finish: 84.656, speaker: "TRAINEE", tape: false, radio: false, text: "Then I'll look at that farm. From above, before anyone can tidy it up." },
	"story.c02.b00": { bank: "voiceBank01", start: 84.906, finish: 93.212, speaker: "TEAL", tape: true, radio: false, text: "I dropped beacons on the way in. Low power, my own frequency. If anyone ever follows me, I wanted it to be someone who knew the song." },
	"story.c02.b01": { bank: "voiceBank01", start: 93.462, finish: 97.920, speaker: "SERA", tape: false, radio: false, text: "He used to tune that pass on Sundays. Said it was the only place the tower couldn't talk to him." },
	"story.c02.b02": { bank: "voiceBank01", start: 98.170, finish: 107.019, speaker: "SERA", tape: false, radio: false, text: "Recovery followed the beacons into the snowy pass. His receiver was in the rocks. Cracked case, memory intact. He meant us to find it." },
	"story.c02.b03": { bank: "voiceBank01", start: 107.269, finish: 115.779, speaker: "TEAL", tape: true, radio: false, text: "There's a radar inside our own training box. Dug into the bowl north of the pass. Nobody signed for it. I checked the ledger three times." },
	"story.c02.b04": { bank: "voiceBank01", start: 116.029, finish: 123.375, speaker: "TEAL", tape: true, radio: false, text: "Somebody wanted to watch trainees. Not the sky. Trainees. Think about why you'd want to know when the kids fly." },
	"story.c02.b05": { bank: "voiceBank01", start: 123.625, finish: 131.062, speaker: "SERA", tape: false, radio: false, text: "If it's real, it's been watching every pattern you've flown for a year. Command wants it gone quietly. I want it photographed first." },
	"story.c02.b06": { bank: "voiceBank01", start: 131.312, finish: 135.120, speaker: "TRAINEE", tape: false, radio: false, text: "If I just blow it up, it's a rumour. If I look at it first, it's a crime." },
	"story.c03.b00": { bank: "voiceBank01", start: 135.370, finish: 145.037, speaker: "TEAL", tape: true, radio: false, text: "The Teklan farmers let me hide a tape in a seed tin. The old woman asked my name, not my rank. Nobody at Varda has asked my name in ten years." },
	"story.c03.b01": { bank: "voiceBank01", start: 145.287, finish: 154.263, speaker: "SERA", tape: false, radio: false, text: "The radar's memory names that orchard. Three days later somebody ordered it evacuated. Now there are patrols firing on the evacuation trucks." },
	"story.c03.b02": { bank: "voiceBank01", start: 154.513, finish: 160.818, speaker: "SERA", tape: false, radio: false, text: "They're not shooting at farmers. They're shooting at a seed tin. That's how badly someone wants Teal's tape back." },
	"story.c03.b03": { bank: "voiceBank01", start: 161.068, finish: 168.190, speaker: "RUSK", tape: false, radio: false, text: "...three officers at Varda are being reassigned tonight. Their names are already off the roster. Nobody will ask. Nobody ever asks." },
	"story.c03.b04": { bank: "voiceBank01", start: 168.440, finish: 174.400, speaker: "TEAL", tape: true, radio: false, text: "The couriers carry patrol routes high over the orchard hills. Their crews guide the guns onto the trucks." },
	"story.c03.b05": { bank: "voiceBank01", start: 174.650, finish: 181.214, speaker: "SERA", tape: false, radio: false, text: "Three transports above the hills, with escorts hidden by two jammers. Find the transports and the families have a road out." },
	"story.c03.b06": { bank: "voiceBank01", start: 181.464, finish: 184.570, speaker: "TRAINEE", tape: false, radio: false, text: "Those trucks are carrying somebody who asked his name. They get out." },
	"story.c04.b00": { bank: "voiceBank01", start: 184.820, finish: 193.975, speaker: "SERA", tape: false, radio: false, text: "The convoy made it. The old woman's granddaughter drove the lead truck. She marked three silos on the map with her thumb. 'Those smell wrong.'" },
	"story.c04.b01": { bank: "voiceBank01", start: 194.225, finish: 202.191, speaker: "TEAL", tape: true, radio: false, text: "Three tanks under grain permits. Aviation fuel. The farmers know the difference, they just can't prove it. A fuel ledger would prove it." },
	"story.c04.b02": { bank: "voiceBank01", start: 202.441, finish: 209.677, speaker: "TEAL", tape: true, radio: false, text: "Sparrow. Every unmarked silo in that valley is somebody's winter. Don't be the one who makes them hungry to make a point." },
	"story.c04.b03": { bank: "voiceBank01", start: 209.927, finish: 215.449, speaker: "SERA", tape: false, radio: false, text: "He wrote that one for you. He never wrote anything for me. I'm choosing not to be hurt by that today." },
	"story.c04.b04": { bank: "voiceBank01", start: 215.699, finish: 224.484, speaker: "TEAL", tape: true, radio: false, text: "Vulture Lead followed me into the pass. He wasn't chasing a deserter. You don't chase deserters at night with your lights off. He was erasing a witness." },
	"story.c04.b05": { bank: "voiceBank01", start: 224.734, finish: 230.146, speaker: "SERA", tape: false, radio: false, text: "If the fuel burns, he'll come looking for you over the works. You don't owe him a duel. Bring yourself home." },
	"story.c04.b06": { bank: "voiceBank01", start: 230.396, finish: 233.517, speaker: "TRAINEE", tape: false, radio: false, text: "Three thumbprints. Three fires. Then I'm leaving him in the dark." },
	"story.c05.b00": { bank: "voiceBank01", start: 233.767, finish: 241.660, speaker: "SERA", tape: false, radio: false, text: "You got clear of Vulture Lead. His orders kept repeating on guard; we recorded them. Every one bears a governor's name. He died in spring." },
	"story.c05.b01": { bank: "voiceBank01", start: 241.910, finish: 249.473, speaker: "TEAL", tape: true, radio: false, text: "Kiro talks to Lira. Lira talks to Merel. Merel talks to the harbours. Start at the quays; listen back up the chain." },
	"story.c05.b02": { bank: "voiceBank01", start: 249.723, finish: 255.299, speaker: "SERA", tape: false, radio: false, text: "I wiped his name off my board this morning. Then I wrote it back. I'm not ready to decide what he is." },
	"story.c05.b03": { bank: "voiceBank01", start: 255.549, finish: 260.982, speaker: "TEAL", tape: true, radio: false, text: "On the coast, look at what the cranes unload. The uniforms tell you nothing. The crates do." },
	"story.c05.b04": { bank: "voiceBank01", start: 261.232, finish: 267.409, speaker: "SERA", tape: false, radio: false, text: "Iron Coast. Military stores beside a fish market. The Marshal put his war where he knew we'd hesitate." },
	"story.c05.b05": { bank: "voiceBank01", start: 267.659, finish: 273.858, speaker: "SERA", tape: false, radio: false, text: "Workers are two blocks from those quays. The ships and tankers are his supply line. Their neighbours are not." },
	"story.c05.b06": { bank: "voiceBank01", start: 274.108, finish: 276.094, speaker: "TRAINEE", tape: false, radio: false, text: "He's right. I'll hesitate. Then I'll aim." },
	"story.c06.b00": { bank: "voiceBank01", start: 276.344, finish: 283.320, speaker: "TEAL", tape: true, radio: false, text: "Kiro keeps an archive. Every forged order, filed, because forgers are vain. It's the only honest thing on the plateau." },
	"story.c06.b01": { bank: "voiceBank01", start: 283.570, finish: 289.111, speaker: "RUSK", tape: false, radio: false, text: "Declare the emergency first. Find the reason after. In a year, nobody has asked me for the reason." },
	"story.c06.b02": { bank: "voiceBank01", start: 289.361, finish: 296.171, speaker: "SERA", tape: false, radio: false, text: "The harbour traffic gave us Kiro's signing key. A key alone is a rumour. We need Lira and Merel's logs with the same signature." },
	"story.c06.b03": { bank: "voiceBank01", start: 296.421, finish: 304.962, speaker: "TEAL", tape: true, radio: false, text: "Lira and Merel sit on opposite ridges and hate each other's weather. Lira lies, Merel repeats her. The west ridge still hears the farms." },
	"story.c06.b04": { bank: "voiceBank01", start: 305.212, finish: 313.057, speaker: "SERA", tape: false, radio: false, text: "Three logs, one signature. Send them home to Varda. Its island transmitter can reach the farms without borrowing his voice." },
	"story.c06.b05": { bank: "voiceBank01", start: 313.307, finish: 318.768, speaker: "TEAL", tape: true, radio: false, text: "I came home through the pass. Not the pretty way. The way you take when you don't want to be seen coming home." },
	"story.c06.b06": { bank: "voiceBank01", start: 319.018, finish: 322.972, speaker: "TRAINEE", tape: false, radio: false, text: "His own words, in his own voice, on their own relay. He'd have liked that." },
	"story.c07.b00": { bank: "voiceBank01", start: 323.222, finish: 330.839, speaker: "SERA", tape: false, radio: false, text: "Three stations, one signature. Varda's island transmitter has the orders and the governor's death certificate. Thirty-five seconds." },
	"story.c07.b01": { bank: "voiceBank01", start: 331.089, finish: 338.207, speaker: "TEAL", tape: true, radio: false, text: "A clear signal needs time. Don't give them a hero. Give them thirty-five seconds and a hero is beside the point." },
	"story.c07.b02": { bank: "voiceBank01", start: 338.457, finish: 345.821, speaker: "SERA", tape: false, radio: false, text: "He recorded that two weeks before he vanished. Thirty-five seconds. He'd already timed it. He knew exactly what this would take." },
	"story.c07.b03": { bank: "voiceBank01", start: 346.071, finish: 349.938, speaker: "SERA", tape: false, radio: false, text: "I'm staying in the tower. In case you were wondering. I'm not leaving my chair for them." },
	"story.c07.b04": { bank: "voiceBank01", start: 350.188, finish: 352.364, speaker: "TRAINEE", tape: false, radio: false, text: "Keep the lights on, Sera. I'll keep the sky." },
	"story.c08.b00": { bank: "voiceBank01", start: 352.614, finish: 357.349, speaker: "SERA", tape: false, radio: false, text: "Three garrisons heard it. Two stood down. Their people are coming ashore to join us." },
	"story.c08.b01": { bank: "voiceBank01", start: 357.599, finish: 363.773, speaker: "SERA", tape: false, radio: false, text: "Three loyalist frigates cover the landing under the weather. The command ship carries a green beacon and most of our hope." },
	"story.c08.b02": { bank: "voiceBank01", start: 364.023, finish: 372.989, speaker: "TEAL", tape: true, radio: false, text: "Storms ground frightened people. They don't ground orders, or fuel, or the people who own them. When the weather's bad, that's when they move." },
	"story.c08.b03": { bank: "voiceBank02", start: 0.250, finish: 6.652, speaker: "TEAL", tape: true, radio: false, text: "If I don't get home, leave the lane open for the next one. That's the job. There isn't a second part." },
	"story.c08.b04": { bank: "voiceBank02", start: 6.902, finish: 12.816, speaker: "SERA", tape: false, radio: false, text: "The frigate captain was at his wing ceremony. Half this coast was. The Marshal forgot that we all remember." },
	"story.c08.b05": { bank: "voiceBank02", start: 13.066, finish: 15.092, speaker: "TRAINEE", tape: false, radio: false, text: "Green beacon. I'll stay close enough to read it." },
	"story.c09.b00": { bank: "voiceBank02", start: 15.342, finish: 20.097, speaker: "SERA", tape: false, radio: false, text: "And then the Marshal answered. Fire at the orchard. A line of guns along the rivers." },
	"story.c09.b01": { bank: "voiceBank02", start: 20.347, finish: 28.742, speaker: "RUSK", tape: false, radio: false, text: "Varda Rim has broadcast enemy propaganda. It is a hostile station. The Teklan orchard sheltered the source. There will be no further warnings." },
	"story.c09.b02": { bank: "voiceBank02", start: 28.992, finish: 37.218, speaker: "SERA", tape: false, radio: false, text: "The orchard burned at noon. The old woman is alive. Her granddaughter is alive. The seed tin is ash. That's my report, and I hate it." },
	"story.c09.b03": { bank: "voiceBank02", start: 37.468, finish: 42.176, speaker: "SERA", tape: false, radio: false, text: "I asked you to broadcast. I'd ask again. I need you to know that I'd ask again." },
	"story.c09.b04": { bank: "voiceBank02", start: 42.426, finish: 45.453, speaker: "TRAINEE", tape: false, radio: false, text: "The rain has passed. The line hasn't. I'll take the valleys." },
	"story.c10.b00": { bank: "voiceBank02", start: 45.703, finish: 52.343, speaker: "SERA", tape: false, radio: false, text: "The old woman heard Teal in her kitchen before the fire. She says he sounded tired. Now her neighbours are flying out over his saddle." },
	"story.c10.b01": { bank: "voiceBank02", start: 52.593, finish: 60.612, speaker: "SERA", tape: false, radio: false, text: "Teal flew that saddle on his checkride. Vulture Two signed the card. I pulled it last night. The handwriting matches the forged orders." },
	"story.c10.b02": { bank: "voiceBank02", start: 60.862, finish: 67.268, speaker: "TEAL", tape: true, radio: false, text: "Two civilian airliners. One cannot climb. Somebody will have to leave the high sky to keep the lower one safe." },
	"story.c10.b03": { bank: "voiceBank02", start: 67.518, finish: 70.546, speaker: "TRAINEE", tape: false, radio: false, text: "Then I'll fly his checkride for him. Properly, this time." },
	"story.c11.b00": { bank: "voiceBank02", start: 70.796, finish: 77.692, speaker: "SERA", tape: false, radio: false, text: "The eight towers in that crater are the Marshal's command array. The antennas up there are his. So is the pilot waiting above them." },
	"story.c11.b01": { bank: "voiceBank02", start: 77.942, finish: 87.728, speaker: "VULTURE TWO", tape: false, radio: false, text: "Varda trainee, this is Vulture Two. I taught your instructor to fly. I know what he'd try over that crater. Turn home. Nobody has to watch." },
	"story.c11.b02": { bank: "voiceBank02", start: 87.978, finish: 95.812, speaker: "TEAL", tape: true, radio: false, text: "Vulture Two taught me that an order is not the same as a duty. Then he forgot. If you meet him, remind him. Loudly." },
	"story.c11.b03": { bank: "voiceBank02", start: 96.062, finish: 101.560, speaker: "SERA", tape: false, radio: false, text: "He's challenged your call sign in daylight. He wants you above the crater, where he can see your face." },
	"story.c11.b04": { bank: "voiceBank02", start: 101.810, finish: 105.978, speaker: "SERA", tape: false, radio: false, text: "If he ejects, mark where he lands. We need a witness who can answer back." },
	"story.c11.b05": { bank: "voiceBank02", start: 106.228, finish: 107.003, speaker: "TRAINEE", tape: false, radio: false, text: "Then he'll see it." },
	"story.c12.b00": { bank: "voiceBank02", start: 107.253, finish: 113.042, speaker: "SERA", tape: false, radio: false, text: "Vulture Two ejected. Marines lifted him out of the crater. He asked if you were Teal's. I said yes." },
	"story.c12.b01": { bank: "voiceBank02", start: 113.292, finish: 121.036, speaker: "VULTURE TWO", tape: false, radio: false, text: "He was the best I ever signed off. Tell the kid the handwriting was mine. All of it. I'm done lying to pilots." },
	"story.c12.b02": { bank: "voiceBank02", start: 121.286, finish: 129.059, speaker: "TEAL", tape: true, radio: false, text: "I made a paper copy. Radios get jammed. Ink still travels. It's in the harbour master's safe, and she doesn't like the Marshal either." },
	"story.c12.b03": { bank: "voiceBank02", start: 129.309, finish: 138.095, speaker: "SERA", tape: false, radio: false, text: "The harbour master's copy and Vulture Two's statement are on one slow plane. Airships are jamming the ravine. Fighters are waiting beyond it." },
	"story.c12.b04": { bank: "voiceBank02", start: 138.345, finish: 145.407, speaker: "SERA", tape: false, radio: false, text: "The signatures, his tapes, a living witness on paper. If that plane falls, command gets to call him a deserter again." },
	"story.c12.b05": { bank: "voiceBank02", start: 145.657, finish: 146.677, speaker: "TRAINEE", tape: false, radio: false, text: "Then it doesn't fall." },
	"story.c13.b00": { bank: "voiceBank02", start: 146.927, finish: 156.160, speaker: "SERA", tape: false, radio: false, text: "The evidence plane is clear. Its papers point to the crown station on the ice coast. Missiles are closing on the dish; we need its archive intact." },
	"story.c13.b01": { bank: "voiceBank02", start: 156.410, finish: 165.419, speaker: "TEAL", tape: true, radio: false, text: "At the crown station I left the order that started all of this. The first one. With his real signature, before he learned to use dead men's names." },
	"story.c13.b02": { bank: "voiceBank02", start: 165.669, finish: 170.770, speaker: "TEAL", tape: true, radio: false, text: "I didn't take it with me. I didn't trust myself to get home. I trusted the dish." },
	"story.c13.b03": { bank: "voiceBank02", start: 171.020, finish: 178.031, speaker: "SERA", tape: false, radio: false, text: "He didn't trust himself to get home. He said it out loud, to a tape, and flew anyway. I keep rewinding that part." },
	"story.c13.b04": { bank: "voiceBank02", start: 178.281, finish: 180.705, speaker: "TRAINEE", tape: false, radio: false, text: "He trusted the dish. I can do that much." },
	"story.c14.b00": { bank: "voiceBank02", start: 180.955, finish: 193.279, speaker: "LOG", tape: false, radio: false, text: "ARCHIVE RECOVERED. ORDER 0001. 'Declare regional emergency. Suspend parliament. Assume air command.' Signed: RUSK, AIR MARSHAL." },
	"story.c14.b01": { bank: "voiceBank02", start: 193.529, finish: 200.439, speaker: "SERA", tape: false, radio: false, text: "Rusk. He gave the speech at Teal's wing ceremony. He told us the sky belongs to whoever is willing to be up in it." },
	"story.c14.b02": { bank: "voiceBank02", start: 200.689, finish: 207.232, speaker: "SERA", tape: false, radio: false, text: "Marines have the paper copy. Now the archive gives us his signature too. And the city still hears nothing but him." },
	"story.c14.b03": { bank: "voiceBank02", start: 207.482, finish: 214.213, speaker: "RUSK", tape: false, radio: false, text: "Citizens. Parliament has fled. Rebel aircraft are over the harbour. Stay inside. Trust the lights. Trust my voice." },
	"story.c14.b04": { bank: "voiceBank02", start: 214.463, finish: 222.411, speaker: "TEAL", tape: true, radio: false, text: "One tower, one voice, one emergency on repeat. He didn't build it to tell anyone anything. He built it so nothing else gets in." },
	"story.c14.b05": { bank: "voiceBank02", start: 222.661, finish: 229.713, speaker: "SERA", tape: false, radio: false, text: "The broadcast relay sits in a block of apartments. He chose that too. The canal is the only dark line through the city." },
	"story.c14.b06": { bank: "voiceBank02", start: 229.963, finish: 234.323, speaker: "TRAINEE", tape: false, radio: false, text: "Everyone in those apartments has been listening to him for a year. I'd like to give them some quiet." },
	"story.c15.b00": { bank: "voiceBank02", start: 234.573, finish: 245.597, speaker: "RUSK", tape: false, radio: false, text: "Trainee. This is Rusk. Teal flew my wing the winter the coast starved while parliament debated. He had talent too. Ask the pass how far it got him." },
	"story.c15.b01": { bank: "voiceBank02", start: 245.847, finish: 250.105, speaker: "SERA", tape: false, radio: false, text: "That's the first time he's used his own name. He wants you to know he's a person. Don't let him." },
	"story.c15.b02": { bank: "voiceBank02", start: 250.355, finish: 254.844, speaker: "TRAINEE", tape: false, radio: false, text: "He flew your wing. Vulture Lead hunted him for you. I'll remember who gave the order." },
	"story.c15.b03": { bank: "voiceBank02", start: 255.094, finish: 262.644, speaker: "SERA", tape: false, radio: false, text: "A loyalist column is crossing the dry coast. Parliament is coming home by road. The ruined town ahead of them still has guns." },
	"story.c15.b04": { bank: "voiceBank02", start: 262.894, finish: 269.537, speaker: "TEAL", tape: true, radio: false, text: "Don't fly for the people giving orders. Fly for the people who have to live beneath them. The man on the net is weather." },
	"story.c15.b05": { bank: "voiceBank02", start: 269.787, finish: 276.405, speaker: "SERA", tape: false, radio: false, text: "He recorded that one at two in the morning. I can hear the hangar heater behind him. I could find that hangar in the dark by that sound." },
	"story.c15.b06": { bank: "voiceBank02", start: 276.655, finish: 281.563, speaker: "SERA", tape: false, radio: false, text: "Clear the bunkers ahead of the column. Stay on their channel until both squads answer from the streets." },
	"story.c15.b07": { bank: "voiceBank02", start: 281.813, finish: 284.023, speaker: "TRAINEE", tape: false, radio: false, text: "Beneath them. Right. The road, then." },
	"story.c16.b00": { bank: "voiceBank02", start: 284.273, finish: 291.322, speaker: "SERA", tape: false, radio: false, text: "Recovery reached the upper pass this morning. They found his aircraft. They found him. He was in the seat. The recorder was still running." },
	"story.c16.b01": { bank: "voiceBank02", start: 291.572, finish: 295.155, speaker: "RECORDER", tape: true, radio: false, text: "RECORDER 7-T. ENTRY 04:12. PLAYBACK." },
	"story.c16.b02": { bank: "voiceBank02", start: 295.405, finish: 304.309, speaker: "TEAL", tape: true, radio: false, text: "Two taps. Sparrow, it's me. Lead is on my tail and I'm out of altitude, so I'm going to stay in the pass a while. The seed trucks need ten minutes." },
	"story.c16.b03": { bank: "voiceBank02", start: 304.559, finish: 312.354, speaker: "TEAL", tape: true, radio: false, text: "I flew that order knowing the price. The tapes are so you never have to take my word for any of it. This part I'm choosing myself." },
	"story.c16.b04": { bank: "voiceBank02", start: 312.604, finish: 319.338, speaker: "TEAL", tape: true, radio: false, text: "Fly the pattern too low and too fast. Nobody ever fixed it. Good. The sky will..." },
	"story.c16.b05": { bank: "voiceBank02", start: 319.588, finish: 327.370, speaker: "SERA", tape: false, radio: false, text: "Witnesses reach parliament tonight. Keep the bridges and quay open. Rusk leads four wingmen over the capital. Vulture Lead is one of them." },
	"story.c16.b06": { bank: "voiceBank02", start: 327.620, finish: 334.931, speaker: "SERA", tape: false, radio: false, text: "I've amended the record myself. 'Aircraft lost with pilot. KILLED, NOT DESERTED.' Command can court-martial the paperwork." },
	"story.c16.b07": { bank: "voiceBank02", start: 335.181, finish: 338.314, speaker: "TRAINEE", tape: false, radio: false, text: "Ten minutes. He bought ten minutes. I'm going to go and spend them." },
	"story.c17.b00": { bank: "voiceBank02", start: 338.564, finish: 345.852, speaker: "SERA", tape: false, radio: false, text: "The wing is broken. Rusk left his wingmen and ran to the coastal relay works. He's alone there with one relay and his own voice." },
	"story.c17.b01": { bank: "voiceBank02", start: 346.102, finish: 353.521, speaker: "RUSK", tape: false, radio: false, text: "Trainee. Land, and I'll tell the city you were misled by a dead man. Fly, and you're the traitor in every history I write." },
	"story.c17.b02": { bank: "voiceBank02", start: 353.771, finish: 358.865, speaker: "TEAL", tape: true, radio: false, text: "When you have the truth, send it in your own voice. You don't have to sound like me. You never did." },
	"story.c17.b03": { bank: "voiceBank02", start: 359.115, finish: 366.588, speaker: "SERA", tape: false, radio: false, text: "I've got every harbour on the net. Every loyalist station is listening for one call sign. Not his. Yours." },
	"story.c17.b04": { bank: "voiceBank02", start: 366.838, finish: 374.075, speaker: "SERA", tape: false, radio: false, text: "Break the generators, run the vent and get clear. When his loop stops, he'll come up alone. Then the sky is yours to answer him." },
	"story.c17.b05": { bank: "voiceBank03", start: 0.250, finish: 4.948, speaker: "TRAINEE", tape: false, radio: false, text: "Marshal. I heard the tape. He didn't sound misled. He sounded like he was counting trucks." },
	"story.c17.b06": { bank: "voiceBank03", start: 5.198, finish: 9.633, speaker: "TRAINEE", tape: false, radio: false, text: "Sera. Varda trainee, checking in. One of three. The other two are for after." },
	"story.c18.b00": { bank: "voiceBank03", start: 9.883, finish: 18.361, speaker: "SERA", tape: false, radio: false, text: "He's down. His relay is dark. Every harbour on the coast is answering. You're on every receiver from the rim to the sea. Say it your way." },
	"story.c18.b01": { bank: "voiceBank03", start: 18.611, finish: 25.022, speaker: "TRAINEE", tape: false, radio: false, text: "This is Varda trainee, transmitting in the clear. The Air Marshal is down. The emergency is over. It never started." },
	"story.c18.b02": { bank: "voiceBank03", start: 25.272, finish: 32.830, speaker: "TRAINEE", tape: false, radio: false, text: "The orders were forged. The names were dead men's. An orchard was burned for a seed tin. Teal flew the pass so the trucks could get out." },
	"story.c18.b03": { bank: "voiceBank03", start: 33.080, finish: 40.625, speaker: "TRAINEE", tape: false, radio: false, text: "His name was Teal. He was not a deserter. Amend your records. For Teal. For the rim. We are coming home." },
	"story.c18.b04": { bank: "voiceBank03", start: 40.875, finish: 47.449, speaker: "SERA", tape: false, radio: false, text: "Varda trainee, Varda Control. Check-in received. Two of three. Come home and make the third in person." },
	"story.c18.b05": { bank: "voiceBank03", start: 47.699, finish: 49.164, speaker: "TEAL", tape: true, radio: false, text: "...the sky will still be there." },
	"story.c18.b06": { bank: "voiceBank03", start: 49.414, finish: 56.442, speaker: "LOG", tape: false, radio: false, text: "VARDA RIM ROSTER. TEAL: KILLED IN ACTION, NOT DESERTED. INSTRUCTOR'S CHAIR: FILLED." },
	"radio.m04.story.1": { bank: "voiceBank03", start: 56.692, finish: 60.745, speaker: "SERA", tape: false, radio: true, text: "SERA: High contacts are guiding the patrols. The trucks need that sky clear." },
	"radio.m04.story.2": { bank: "voiceBank03", start: 60.995, finish: 63.296, speaker: "SERA", tape: false, radio: true, text: "SERA: The road is open. Count the trucks at Varda." },
	"radio.m05.story.1": { bank: "voiceBank03", start: 63.546, finish: 66.985, speaker: "SERA", tape: false, radio: true, text: "SERA: Fuel tanks only. The grain silos beside them feed families." },
	"radio.m05.story.2": { bank: "voiceBank03", start: 67.235, finish: 71.795, speaker: "SERA", tape: false, radio: true, text: "SERA: Vulture flight inbound. Leave the works. Survive; this is no duel." },
	"radio.m05.story.3": { bank: "voiceBank03", start: 72.045, finish: 74.001, speaker: "SERA", tape: false, radio: true, text: "SERA: You are clear. I kept his orders on tape." },
	"radio.m06.story.1": { bank: "voiceBank03", start: 74.251, finish: 77.761, speaker: "SERA", tape: false, radio: true, text: "SERA: Iron Coast ahead. Ships and tankers; leave the market clear." },
	"radio.m06.story.2": { bank: "voiceBank03", start: 78.011, finish: 80.904, speaker: "SERA", tape: false, radio: true, text: "SERA: Harbour traffic copied. We can follow the orders inland." },
	"radio.m07.story.1": { bank: "voiceBank03", start: 81.154, finish: 84.484, speaker: "SERA", tape: false, radio: true, text: "SERA: Copy before you cut. We need the signature, not just wreckage." },
	"radio.m07.story.2": { bank: "voiceBank03", start: 84.734, finish: 86.619, speaker: "SERA", tape: false, radio: true, text: "SERA: Guns have the ridge. Take the canyon." },
	"radio.m08.story.1": { bank: "voiceBank03", start: 86.869, finish: 90.298, speaker: "SERA", tape: false, radio: true, text: "SERA: I am staying in the tower. Keep the bombers away from the transmitter." },
	"radio.m08.story.2": { bank: "voiceBank03", start: 90.548, finish: 93.584, speaker: "SERA", tape: false, radio: true, text: "SERA: Thirty-five seconds sent. Two garrisons are answering." },
	"radio.m09.story.1": { bank: "voiceBank03", start: 93.834, finish: 97.086, speaker: "SERA", tape: false, radio: true, text: "SERA: Green beacon is ours. Clear the guns above the beach." },
	"radio.m09.story.2": { bank: "voiceBank03", start: 97.336, finish: 100.075, speaker: "SERA", tape: false, radio: true, text: "SERA: The landing is through. There is smoke over Teklan." },
	"radio.m10.story.1": { bank: "voiceBank03", start: 100.325, finish: 103.114, speaker: "SERA", tape: false, radio: true, text: "SERA: Keep the valley between you and the long-range guns." },
	"radio.m10.story.2": { bank: "voiceBank03", start: 103.364, finish: 106.226, speaker: "SERA", tape: false, radio: true, text: "SERA: The corridor is open. Two civilian flights are ready." },
	"radio.m11.story.1": { bank: "voiceBank03", start: 106.476, finish: 109.820, speaker: "SERA", tape: false, radio: true, text: "SERA: One airliner cannot climb. Watch both altitude bands." },
	"radio.m11.story.2": { bank: "voiceBank03", start: 110.070, finish: 112.908, speaker: "SERA", tape: false, radio: true, text: "SERA: Both flights are clear. I have a name for that handwriting." },
	"radio.m12.story.1": { bank: "voiceBank03", start: 113.158, finish: 117.047, speaker: "SERA", tape: false, radio: true, text: "SERA: Eight towers. The command array is his; the crater is your way in." },
	"radio.m12.story.2": { bank: "voiceBank03", start: 117.297, finish: 119.294, speaker: "SERA", tape: false, radio: true, text: "SERA: Ejection marked. Marines are moving." },
	"radio.m13.story.1": { bank: "voiceBank03", start: 119.544, finish: 122.047, speaker: "SERA", tape: false, radio: true, text: "SERA: Jammers in the ravine. Clear the plane a channel." },
	"radio.m13.story.2": { bank: "voiceBank03", start: 122.297, finish: 125.047, speaker: "SERA", tape: false, radio: true, text: "SERA: Fighters beyond the fog. Keep them off the evidence plane." },
	"radio.m14.story.1": { bank: "voiceBank03", start: 125.297, finish: 128.190, speaker: "SERA", tape: false, radio: true, text: "SERA: Missiles low over the ice. The dish must keep talking." },
	"radio.m14.story.2": { bank: "voiceBank03", start: 128.440, finish: 132.063, speaker: "SERA", tape: false, radio: true, text: "SERA: Archive received. Order zero-zero-zero-one. Rusk." },
	"radio.m15.story.1": { bank: "voiceBank03", start: 132.313, finish: 135.796, speaker: "SERA", tape: false, radio: true, text: "SERA: Loyalist troops below. Keep Rusk's armour off their streets." },
	"radio.m15.story.2": { bank: "voiceBank03", start: 136.046, finish: 138.418, speaker: "SERA", tape: false, radio: true, text: "SERA: Bombers incoming. They are turning on the city." },
	"radio.m16.story.1": { bank: "voiceBank03", start: 138.668, finish: 140.505, speaker: "SERA", tape: false, radio: true, text: "SERA: Clear the bunkers ahead of the column." },
	"radio.m16.story.2": { bank: "voiceBank03", start: 140.755, finish: 144.492, speaker: "SERA", tape: false, radio: true, text: "SERA: Both squads answering from the streets. Parliament has a road home." },
	"radio.m17.story.1": { bank: "voiceBank03", start: 144.742, finish: 148.436, speaker: "SERA", tape: false, radio: true, text: "SERA: Rusk leads four wingmen. Vulture Lead is back over the capital." },
	"radio.m17.story.2": { bank: "voiceBank03", start: 148.686, finish: 151.366, speaker: "SERA", tape: false, radio: true, text: "SERA: He left his wing. Rusk is running for the coast." },
	"radio.m18.story.1": { bank: "voiceBank03", start: 151.616, finish: 155.371, speaker: "SERA", tape: false, radio: true, text: "SERA: Generators first. Then the central vent. Leave yourself a way out." },
	"radio.m18.story.2": { bank: "voiceBank03", start: 155.621, finish: 159.295, speaker: "SERA", tape: false, radio: true, text: "SERA: You are clear. His loop has stopped. Rusk is coming up alone." },
	"radio.m01.p1.beat": { bank: "voiceBank03", start: 159.545, finish: 163.067, speaker: "SERA", tape: false, radio: true, text: "Six bombers, our paint and codes. Stop them before the north coast." },
	"radio.m02.p1.beat": { bank: "voiceBank03", start: 163.317, finish: 166.298, speaker: "SERA", tape: false, radio: true, text: "SERA: Follow the power line north. Their bombers are parked on the farm." },
	"radio.m02.p1.chatter1": { bank: "voiceBank03", start: 166.548, finish: 170.056, speaker: "BROADCAST", tape: false, radio: true, text: "FARM CONTROL: Bombers, start engines! Get them off the ground!" },
	"radio.m02.p1.chatter2": { bank: "voiceBank03", start: 170.306, finish: 173.104, speaker: "SERA", tape: false, radio: true, text: "SERA: Four down. Their guns are still up, watch the base edges." },
	"radio.m02.p1.chatter3": { bank: "voiceBank03", start: 173.354, finish: 176.294, speaker: "BROADCAST", tape: false, radio: true, text: "FARM CONTROL: The pads are burning. Nobody takes off from here." },
	"radio.m02.p1.chatter4": { bank: "voiceBank03", start: 176.544, finish: 178.568, speaker: "MARINE", tape: false, radio: true, text: "LANTERN 2: One bomber left. Finish it, trainee." },
	"radio.m03.p1.beat": { bank: "voiceBank03", start: 178.818, finish: 181.961, speaker: "SERA", tape: false, radio: true, text: "SERA: Enemy airspace. Site one is on the ridge north-west of you." },
	"radio.m03.p1.chatter1": { bank: "voiceBank03", start: 182.211, finish: 184.194, speaker: "MARINE", tape: false, radio: true, text: "LANTERN 2: Dome down. Good hit, trainee." },
	"radio.m03.p1.chatter2": { bank: "voiceBank03", start: 184.444, finish: 187.780, speaker: "SERA", tape: false, radio: true, text: "SERA: Five domes down. Site two is on the saddle west-north-west." },
	"radio.m03.p1.chatter3": { bank: "voiceBank03", start: 188.030, finish: 190.131, speaker: "MARINE", tape: false, radio: true, text: "LANTERN 2: One dome left. Finish it and we go home." },
	"radio.m03.p3.landing1": { bank: "voiceBank03", start: 190.381, finish: 194.499, speaker: "RIM TOWER", tape: false, radio: true, text: "RIM TOWER: Trainee, gear check. Cleared to land, runway three-six." },
	"radio.m03.p3.landing2": { bank: "voiceBank03", start: 194.749, finish: 197.075, speaker: "RIM TOWER", tape: false, radio: true, text: "RIM TOWER: Runway in sight. You're on the centreline." },
	"radio.m03.p3.landing3": { bank: "voiceBank03", start: 197.325, finish: 200.576, speaker: "RIM TOWER", tape: false, radio: true, text: "RIM TOWER: Short final. Glide path is good, hold it there." },
	"radio.m03.p3.landing4": { bank: "voiceBank03", start: 200.826, finish: 202.355, speaker: "RIM TOWER", tape: false, radio: true, text: "RIM TOWER: Touchdown. Nice and gentle." },
	"radio.m03.p3.landing5": { bank: "voiceBank03", start: 202.605, finish: 205.875, speaker: "RIM TOWER", tape: false, radio: true, text: "RIM TOWER: Welcome home. Sera wants that film before you unstrap." },
};
